   196→// RunForAllStrategies runs a test function for each strategy in parallel.
   197→// This reduces boilerplate for tests that need to verify behavior across all strategies.
   198→// Each subtest gets its own TestEnv with a feature branch ready for testing.
   199→func RunForAllStrategies(t *testing.T, testFn func(t *testing.T, env *TestEnv, strategyName string)) {
   200→	t.Helper()
   201→	for _, strat := range AllStrategies() {
   202→		strat := strat // capture for parallel
   203→		t.Run(strat, func(t *testing.T) {
   204→			t.Parallel()
   205→			env := NewFeatureBranchEnv(t, strat)
   206→			testFn(t, env, strat)
   207→		})
   208→	}
   209→}
