   262→	// Configure git user for commits
   263→	cfg, err := repo.Config()
   264→	if err != nil {
   265→		env.T.Fatalf("failed to get repo config: %v", err)
   266→	}
   267→	cfg.User.Name = "Test User"
   268→	cfg.User.Email = "test@example.com"
   269→
   270→	// Disable GPG signing for test commits (prevents failures if user has commit.gpgsign=true globally)
   271→	if cfg.Raw == nil {
   272→		cfg.Raw = config.New()
   273→	}
   274→	cfg.Raw.Section("commit").SetOption("gpgsign", "false")
   275→
   276→	if err := repo.SetConfig(cfg); err != nil {
   277→		env.T.Fatalf("failed to set repo config: %v", err)
   278→	}
   279→}
