   305→// initEntireInternal is the common implementation for InitEntire variants.
   306→func (env *TestEnv) initEntireInternal(strategyName string, agentName agent.AgentName, strategyOptions map[string]any) {
   307→	env.T.Helper()
   308→
   309→	// Create .entire directory structure
   310→	entireDir := filepath.Join(env.RepoDir, ".entire")
   311→	if err := os.MkdirAll(entireDir, 0o755); err != nil {
   312→		env.T.Fatalf("failed to create .entire directory: %v", err)
   313→	}
   314→
   315→	// Create tmp directory
   316→	tmpDir := filepath.Join(entireDir, "tmp")
   317→	if err := os.MkdirAll(tmpDir, 0o755); err != nil {
   318→		env.T.Fatalf("failed to create .entire/tmp directory: %v", err)
   319→	}
   320→
   321→	// Write settings.json
   322→	settings := map[string]any{
   323→		"strategy":  strategyName,
   324→		"local_dev": true, // Note: git-triggered hooks won't work (path is relative); tests call hooks via getTestBinary() instead
   325→	}
   326→	// Only add agent if specified (otherwise defaults to claude-code)
   327→	if agentName != "" {
   328→		settings["agent"] = string(agentName)
   329→	}
   330→	if strategyOptions != nil {
   331→		settings["strategy_options"] = strategyOptions
   332→	}
   333→	data, err := jsonutil.MarshalIndentWithNewline(settings, "", "  ")
   334→	if err != nil {
   335→		env.T.Fatalf("failed to marshal settings: %v", err)
   336→	}
   337→	settingsPath := filepath.Join(entireDir, paths.SettingsFileName)
   338→	if err := os.WriteFile(settingsPath, data, 0o644); err != nil {
   339→		env.T.Fatalf("failed to write %s: %v", paths.SettingsFileName, err)
   340→	}
   341→}
