  1059→// GitCommitWithTrailerRemoved stages and commits files, simulating what happens when
  1060→// a user removes the Entire-Checkpoint trailer during commit message editing.
  1061→// This tests the opt-out behavior where removing the trailer skips condensation.
  1062→func (env *TestEnv) GitCommitWithTrailerRemoved(message string, files ...string) {
  1063→	env.T.Helper()
  1064→
  1065→	// Stage files using go-git
  1066→	for _, file := range files {
  1067→		env.GitAdd(file)
  1068→	}
  1069→
  1070→	// Create a temp file for the commit message (prepare-commit-msg hook modifies this)
  1071→	msgFile := filepath.Join(env.RepoDir, ".git", "COMMIT_EDITMSG")
  1072→	if err := os.WriteFile(msgFile, []byte(message), 0o644); err != nil {
  1073→		env.T.Fatalf("failed to write commit message file: %v", err)
  1074→	}
  1075→
  1076→	// Run prepare-commit-msg hook using the shared binary.
  1077→	// Set ENTIRE_TEST_TTY=1 to simulate human (this tests the editor flow where
  1078→	// the user removes the trailer before committing).
  1079→	prepCmd := exec.Command(getTestBinary(), "hooks", "git", "prepare-commit-msg", msgFile)
  1080→	prepCmd.Dir = env.RepoDir
  1081→	prepCmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=1")
  1082→	if output, err := prepCmd.CombinedOutput(); err != nil {
  1083→		env.T.Logf("prepare-commit-msg output: %s", output)
  1084→	}
  1085→
  1086→	// Read the modified message (with trailer added by hook)
  1087→	modifiedMsg, err := os.ReadFile(msgFile)
  1088→	if err != nil {
  1089→		env.T.Fatalf("failed to read modified commit message: %v", err)
  1090→	}
  1091→
  1092→	// REMOVE the Entire-Checkpoint trailer (simulating user editing the message)
  1093→	lines := strings.Split(string(modifiedMsg), "\n")
  1094→	var cleanedLines []string
  1095→	for _, line := range lines {
  1096→		// Skip the trailer and the comments about it
  1097→		if strings.HasPrefix(line, "Entire-Checkpoint:") {
  1098→			continue
  1099→		}
  1100→		if strings.Contains(line, "Remove the Entire-Checkpoint trailer") {
  1101→			continue
  1102→		}
  1103→		if strings.Contains(line, "trailer will be added to your next commit") {
  1104→			continue
  1105→		}
  1106→		cleanedLines = append(cleanedLines, line)
  1107→	}
  1108→	cleanedMsg := strings.TrimRight(strings.Join(cleanedLines, "\n"), "\n") + "\n"
  1109→
  1110→	// Create the commit using go-git with the cleaned message (no trailer)
  1111→	repo, err := git.PlainOpen(env.RepoDir)
  1112→	if err != nil {
  1113→		env.T.Fatalf("failed to open git repo: %v", err)
  1114→	}
  1115→
  1116→	worktree, err := repo.Worktree()
