   654→// GetRewindPoints returns available rewind points using the CLI.
   655→func (env *TestEnv) GetRewindPoints() []RewindPoint {
   656→	env.T.Helper()
   657→
   658→	// Run rewind --list using the shared binary
   659→	cmd := exec.Command(getTestBinary(), "rewind", "--list")
   660→	cmd.Dir = env.RepoDir
   661→	cmd.Env = env.cliEnv()
   662→
   663→	output, err := cmd.CombinedOutput()
   664→	if err != nil {
   665→		env.T.Fatalf("rewind --list failed: %v\nOutput: %s", err, output)
   666→	}
   667→
   668→	// Parse JSON output
   669→	var jsonPoints []struct {
   670→		ID               string `json:"id"`
   671→		Message          string `json:"message"`
   672→		MetadataDir      string `json:"metadata_dir"`
   673→		Date             string `json:"date"`
   674→		IsTaskCheckpoint bool   `json:"is_task_checkpoint"`
   675→		ToolUseID        string `json:"tool_use_id"`
   676→		IsLogsOnly       bool   `json:"is_logs_only"`
   677→		CondensationID   string `json:"condensation_id"`
   678→	}
   679→
   680→	if err := json.Unmarshal(output, &jsonPoints); err != nil {
   681→		env.T.Fatalf("failed to parse rewind points: %v\nOutput: %s", err, output)
   682→	}
   683→
   684→	points := make([]RewindPoint, len(jsonPoints))
   685→	for i, jp := range jsonPoints {
   686→		date, _ := time.Parse(time.RFC3339, jp.Date)
   687→		points[i] = RewindPoint{
   688→			ID:               jp.ID,
   689→			Message:          jp.Message,
   690→			MetadataDir:      jp.MetadataDir,
   691→			Date:             date,
   692→			IsTaskCheckpoint: jp.IsTaskCheckpoint,
   693→			ToolUseID:        jp.ToolUseID,
   694→			IsLogsOnly:       jp.IsLogsOnly,
   695→			CondensationID:   jp.CondensationID,
   696→		}
   697→	}
   698→
   699→	return points
   700→}
