   807→		env.T.Fatalf("failed to open git repo: %v", err)
   808→	}
   809→
   810→	// Get the branch reference
   811→	ref, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
   812→	if err != nil {
   813→		// Try as a remote-style ref
   814→		ref, err = repo.Reference(plumbing.ReferenceName("refs/heads/"+branchName), true)
   815→		if err != nil {
   816→			return false
   817→		}
   818→	}
   819→
   820→	// Get the commit
   821→	commit, err := repo.CommitObject(ref.Hash())
   822→	if err != nil {
   823→		return false
   824→	}
   825→
   826→	// Get the tree
   827→	tree, err := commit.Tree()
   828→	if err != nil {
   829→		return false
   830→	}
   831→
   832→	// Check if file exists
   833→	_, err = tree.File(filePath)
   834→	return err == nil
   835→}
