  1257→// GetLatestCheckpointIDFromHistory walks backwards from HEAD on the active branch
  1258→// and returns the checkpoint ID from the first commit that has an Entire-Checkpoint trailer.
  1259→// This verifies that condensation actually happened (commit has trailer) without relying
  1260→// on timestamp-based matching.
  1261→func (env *TestEnv) GetLatestCheckpointIDFromHistory() string {
  1262→	env.T.Helper()
  1263→
  1264→	repo, err := git.PlainOpen(env.RepoDir)
  1265→	if err != nil {
  1266→		env.T.Fatalf("failed to open git repo: %v", err)
  1267→	}
  1268→
  1269→	head, err := repo.Head()
  1270→	if err != nil {
  1271→		env.T.Fatalf("failed to get HEAD: %v", err)
  1272→	}
  1273→
  1274→	commitIter, err := repo.Log(&git.LogOptions{From: head.Hash()})
  1275→	if err != nil {
  1276→		env.T.Fatalf("failed to iterate commits: %v", err)
  1277→	}
  1278→
  1279→	var checkpointID string
  1280→	//nolint:errcheck // ForEach callback handles errors
  1281→	commitIter.ForEach(func(c *object.Commit) error {
  1282→		if cpID, found := trailers.ParseCheckpoint(c.Message); found {
  1283→			checkpointID = cpID.String()
  1284→			return errors.New("stop iteration") // Found it, stop
  1285→		}
  1286→		return nil
  1287→	})
  1288→
  1289→	if checkpointID == "" {
  1290→		env.T.Fatalf("no commit with Entire-Checkpoint trailer found in history")
  1291→	}
  1292→
  1293→	return checkpointID
  1294→}
