  1372→// validateCheckpointSummary validates the root metadata.json (CheckpointSummary).
  1373→func (env *TestEnv) validateCheckpointSummary(v CheckpointValidation) {
  1374→	env.T.Helper()
  1375→
  1376→	summaryPath := CheckpointSummaryPath(v.CheckpointID)
  1377→	content, found := env.ReadFileFromBranch(paths.MetadataBranchName, summaryPath)
  1378→	if !found {
  1379→		env.T.Fatalf("CheckpointSummary not found at %s", summaryPath)
  1380→	}
  1381→
  1382→	var summary checkpoint.CheckpointSummary
  1383→	if err := json.Unmarshal([]byte(content), &summary); err != nil {
  1384→		env.T.Fatalf("Failed to parse CheckpointSummary: %v\nContent: %s", err, content)
  1385→	}
  1386→
  1387→	// Validate checkpoint_id
  1388→	if summary.CheckpointID.String() != v.CheckpointID {
  1389→		env.T.Errorf("CheckpointSummary.CheckpointID = %q, want %q", summary.CheckpointID, v.CheckpointID)
  1390→	}
  1391→
  1392→	// Validate strategy
  1393→	if v.Strategy != "" && summary.Strategy != v.Strategy {
  1394→		env.T.Errorf("CheckpointSummary.Strategy = %q, want %q", summary.Strategy, v.Strategy)
  1395→	}
  1396→
  1397→	// Validate sessions array is populated
  1398→	if len(summary.Sessions) == 0 {
  1399→		env.T.Error("CheckpointSummary.Sessions should have at least one entry")
  1400→	}
  1401→
  1402→	// Validate files_touched
  1403→	if len(v.FilesTouched) > 0 {
  1404→		touchedSet := make(map[string]bool)
  1405→		for _, f := range summary.FilesTouched {
  1406→			touchedSet[f] = true
  1407→		}
  1408→		for _, expected := range v.FilesTouched {
  1409→			if !touchedSet[expected] {
  1410→				env.T.Errorf("CheckpointSummary.FilesTouched missing %q, got %v", expected, summary.FilesTouched)
  1411→			}
  1412→		}
  1413→	}
  1414→
  1415→	// Validate checkpoints_count
  1416→	if v.CheckpointsCount > 0 && summary.CheckpointsCount != v.CheckpointsCount {
  1417→		env.T.Errorf("CheckpointSummary.CheckpointsCount = %d, want %d", summary.CheckpointsCount, v.CheckpointsCount)
  1418→	}
  1419→}
