  1431→	var metadata checkpoint.CommittedMetadata
  1432→	if err := json.Unmarshal([]byte(content), &metadata); err != nil {
  1433→		env.T.Fatalf("Failed to parse CommittedMetadata: %v\nContent: %s", err, content)
  1434→	}
  1435→
  1436→	// Validate checkpoint_id
  1437→	if metadata.CheckpointID.String() != v.CheckpointID {
  1438→		env.T.Errorf("CommittedMetadata.CheckpointID = %q, want %q", metadata.CheckpointID, v.CheckpointID)
  1439→	}
  1440→
  1441→	// Validate session_id
  1442→	if v.SessionID != "" && metadata.SessionID != v.SessionID {
  1443→		env.T.Errorf("CommittedMetadata.SessionID = %q, want %q", metadata.SessionID, v.SessionID)
  1444→	}
  1445→
  1446→	// Validate strategy
  1447→	if v.Strategy != "" && metadata.Strategy != v.Strategy {
  1448→		env.T.Errorf("CommittedMetadata.Strategy = %q, want %q", metadata.Strategy, v.Strategy)
  1449→	}
  1450→
  1451→	// Validate created_at is not zero
  1452→	if metadata.CreatedAt.IsZero() {
  1453→		env.T.Error("CommittedMetadata.CreatedAt should not be zero")
  1454→	}
  1455→
  1456→	// Validate files_touched
  1457→	if len(v.FilesTouched) > 0 {
  1458→		touchedSet := make(map[string]bool)
  1459→		for _, f := range metadata.FilesTouched {
  1460→			touchedSet[f] = true
  1461→		}
  1462→		for _, expected := range v.FilesTouched {
  1463→			if !touchedSet[expected] {
  1464→				env.T.Errorf("CommittedMetadata.FilesTouched missing %q, got %v", expected, metadata.FilesTouched)
  1465→			}
  1466→		}
  1467→	}
  1468→
  1469→	// Validate checkpoints_count
  1470→	if v.CheckpointsCount > 0 && metadata.CheckpointsCount != v.CheckpointsCount {
  1471→		env.T.Errorf("CommittedMetadata.CheckpointsCount = %d, want %d", metadata.CheckpointsCount, v.CheckpointsCount)
  1472→	}
  1473→}
