  1475→// validateTranscriptJSONL validates that full.jsonl exists and is valid JSONL.
  1476→func (env *TestEnv) validateTranscriptJSONL(checkpointID string, expectedContent []string) {
  1477→	env.T.Helper()
  1478→
  1479→	transcriptPath := SessionFilePath(checkpointID, paths.TranscriptFileName)
  1480→	content, found := env.ReadFileFromBranch(paths.MetadataBranchName, transcriptPath)
  1481→	if !found {
  1482→		env.T.Fatalf("Transcript not found at %s", transcriptPath)
  1483→	}
  1484→
  1485→	// Validate it's valid JSONL (each non-empty line should be valid JSON)
  1486→	lines := strings.Split(content, "\n")
  1487→	validLines := 0
  1488→	for i, line := range lines {
  1489→		line = strings.TrimSpace(line)
  1490→		if line == "" {
  1491→			continue
  1492→		}
  1493→		validLines++
  1494→		var obj map[string]any
  1495→		if err := json.Unmarshal([]byte(line), &obj); err != nil {
  1496→			env.T.Errorf("Transcript line %d is not valid JSON: %v\nLine: %s", i+1, err, line)
  1497→		}
  1498→	}
  1499→
  1500→	if validLines == 0 {
  1501→		env.T.Error("Transcript is empty (no valid JSONL lines)")
  1502→	}
  1503→
  1504→	// Validate expected content appears in transcript
  1505→	for _, expected := range expectedContent {
  1506→		if !strings.Contains(content, expected) {
  1507→			env.T.Errorf("Transcript should contain %q", expected)
  1508→		}
  1509→	}
  1510→}
