  1512→// validateContentHash validates that content_hash.txt matches the SHA256 of the transcript.
  1513→func (env *TestEnv) validateContentHash(checkpointID string) {
  1514→	env.T.Helper()
  1515→
  1516→	// Read transcript
  1517→	transcriptPath := SessionFilePath(checkpointID, paths.TranscriptFileName)
  1518→	transcript, found := env.ReadFileFromBranch(paths.MetadataBranchName, transcriptPath)
  1519→	if !found {
  1520→		env.T.Fatalf("Transcript not found at %s", transcriptPath)
  1521→	}
  1522→
  1523→	// Read content hash
  1524→	hashPath := SessionFilePath(checkpointID, "content_hash.txt")
  1525→	storedHash, found := env.ReadFileFromBranch(paths.MetadataBranchName, hashPath)
  1526→	if !found {
  1527→		env.T.Fatalf("Content hash not found at %s", hashPath)
  1528→	}
  1529→	storedHash = strings.TrimSpace(storedHash)
  1530→
  1531→	// Calculate expected hash with sha256: prefix (matches format in committed.go)
  1532→	hash := sha256.Sum256([]byte(transcript))
  1533→	expectedHash := "sha256:" + hex.EncodeToString(hash[:])
  1534→
  1535→	if storedHash != expectedHash {
  1536→		env.T.Errorf("Content hash mismatch:\n  stored:   %s\n  expected: %s", storedHash, expectedHash)
  1537→	}
  1538→}
