  1557→func findModuleRoot() string {
  1558→	// Start from this source file's location and walk up to find go.mod
  1559→	_, thisFile, _, ok := runtime.Caller(0)
  1560→	if !ok {
  1561→		panic("failed to get current file path via runtime.Caller")
  1562→	}
  1563→	dir := filepath.Dir(thisFile)
  1564→
  1565→	for {
  1566→		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
  1567→			return dir
  1568→		}
  1569→		parent := filepath.Dir(dir)
  1570→		if parent == dir {
  1571→			panic("could not find go.mod starting from " + thisFile)
  1572→		}
  1573→		dir = parent
  1574→	}
  1575→}
