   256→// ActionHandler defines strategy-specific side effects for state transitions.
   257→// The compiler enforces that every strategy-specific action has a handler.
   258→type ActionHandler interface {
   259→	HandleCondense(state *State) error
   260→	HandleCondenseIfFilesTouched(state *State) error
   261→	HandleDiscardIfNoFiles(state *State) error
   262→	HandleWarnStaleSession(state *State) error
   263→}
   264→
   265→// NoOpActionHandler is a default ActionHandler where all methods are no-ops.
   266→// Embed this in handler structs to only override the methods you need.
   267→type NoOpActionHandler struct{}
   268→
   269→func (NoOpActionHandler) HandleCondense(_ *State) error               { return nil }
   270→func (NoOpActionHandler) HandleCondenseIfFilesTouched(_ *State) error { return nil }
   271→func (NoOpActionHandler) HandleDiscardIfNoFiles(_ *State) error       { return nil }
   272→func (NoOpActionHandler) HandleWarnStaleSession(_ *State) error       { return nil }
   273→
   274→// ApplyTransition applies a TransitionResult to state: sets the new phase
   275→// unconditionally, then executes all actions. Common actions
   276→// (UpdateLastInteraction, ClearEndedAt) always run regardless of handler
   277→// errors so that bookkeeping fields stay consistent with the new phase.
   278→// Strategy-specific handler actions stop on the first error; subsequent
   279→// handler actions are skipped but common actions continue. Returns the
   280→// first handler error, or nil.
   281→func ApplyTransition(state *State, result TransitionResult, handler ActionHandler) error {
   282→	logCtx := logging.WithComponent(context.Background(), "session")
   283→
   284→	actionStrs := make([]string, len(result.Actions))
   285→	for i, a := range result.Actions {
   286→		actionStrs[i] = a.String()
   287→	}
   288→	logging.Debug(logCtx, "ApplyTransition",
   289→		slog.String("session_id", state.SessionID),
   290→		slog.String("old_phase", string(state.Phase)),
   291→		slog.String("new_phase", string(result.NewPhase)),
   292→		slog.String("actions", strings.Join(actionStrs, ",")),
   293→	)
   294→
   295→	state.Phase = result.NewPhase
   296→
   297→	var handlerErr error
   298→	for _, action := range result.Actions {
   299→		switch action {
   300→		// Common actions: always applied, even after a handler error.
   301→		case ActionUpdateLastInteraction:
   302→			now := time.Now()
   303→			state.LastInteractionTime = &now
   304→		case ActionClearEndedAt:
   305→			state.EndedAt = nil
   306→
   307→		// Strategy-specific actions: skip remaining after the first handler error.
   308→		case ActionCondense:
   309→			if handlerErr == nil {
   310→				if err := handler.HandleCondense(state); err != nil {
   311→					handlerErr = fmt.Errorf("%s: %w", action, err)
   312→				}
   313→			}
   314→		case ActionCondenseIfFilesTouched:
   315→			if handlerErr == nil {
   316→				if err := handler.HandleCondenseIfFilesTouched(state); err != nil {
   317→					handlerErr = fmt.Errorf("%s: %w", action, err)
   318→				}
   319→			}
   320→		case ActionDiscardIfNoFiles:
   321→			if handlerErr == nil {
   322→				if err := handler.HandleDiscardIfNoFiles(state); err != nil {
   323→					handlerErr = fmt.Errorf("%s: %w", action, err)
   324→				}
   325→			}
   326→		case ActionWarnStaleSession:
   327→			if handlerErr == nil {
   328→				if err := handler.HandleWarnStaleSession(state); err != nil {
   329→					handlerErr = fmt.Errorf("%s: %w", action, err)
   330→				}
   331→			}
   332→		default:
   333→			if handlerErr == nil {
   334→				handlerErr = fmt.Errorf("unhandled action: %s", action)
   335→			}
   336→		}
   337→	}
   338→	return handlerErr
   339→}
