   341→// MermaidDiagram generates a Mermaid state diagram from the transition table.
   342→// The diagram is derived by calling Transition() for representative context
   343→// variants per phase/event, so it stays in sync with the implementation.
   344→func MermaidDiagram() string {
   345→	var b strings.Builder
   346→	b.WriteString("stateDiagram-v2\n")
   347→
   348→	// State declarations with descriptions.
   349→	b.WriteString("    state \"IDLE\" as idle\n")
   350→	b.WriteString("    state \"ACTIVE\" as active\n")
   351→	b.WriteString("    state \"ENDED\" as ended\n")
   352→	b.WriteString("\n")
   353→
   354→	// Context variants for GitCommit: rebase, files/no-files.
   355→	type contextVariant struct {
   356→		label string
   357→		ctx   TransitionContext
   358→	}
   359→
   360→	// For each phase/event, generate edges.
   361→	for _, phase := range allPhases {
   362→		for _, event := range allEvents {
   363→			var variants []contextVariant
   364→			switch {
   365→			case event == EventGitCommit && phase == PhaseEnded:
   366→				// HasFilesTouched only affects PhaseEnded transitions;
   367→				// other phases produce identical edges for both values.
   368→				variants = []contextVariant{
   369→					{"[files]", TransitionContext{HasFilesTouched: true}},
   370→					{"[no files]", TransitionContext{HasFilesTouched: false}},
   371→					{"[rebase]", TransitionContext{IsRebaseInProgress: true}},
   372→				}
   373→			case event == EventGitCommit:
   374→				variants = []contextVariant{
   375→					{"", TransitionContext{}},
   376→					{"[rebase]", TransitionContext{IsRebaseInProgress: true}},
   377→				}
   378→			default:
   379→				variants = []contextVariant{
   380→					{"", TransitionContext{}},
   381→				}
   382→			}
   383→
   384→			for _, v := range variants {
   385→				result := Transition(phase, event, v.ctx)
   386→
   387→				// Build edge label.
   388→				label := event.String()
   389→				if v.label != "" {
   390→					label += " " + v.label
   391→				}
   392→				if len(result.Actions) > 0 {
   393→					actionNames := make([]string, 0, len(result.Actions))
   394→					for _, a := range result.Actions {
   395→						actionNames = append(actionNames, a.String())
   396→					}
   397→					label += " / " + strings.Join(actionNames, ", ")
   398→				}
   399→
   400→				from := string(phase)
   401→				to := string(result.NewPhase)
   402→
   403→				fmt.Fprintf(&b, "    %s --> %s : %s\n", from, to, label)
   404→			}
   405→		}
   406→	}
   407→
   408→	return b.String()
   409→}
