	sess.CreateTranscript("Create file A", []FileChange{
		{Path: "fileA.go", Content: "package main\n\nfunc A() {}\n"},
	})

	// Stop session (becomes IDLE)
	if err := env.SimulateStop(sess.ID, sess.TranscriptPath); err != nil {
