	checkpointIDsAfterSecond := env.GetAllCheckpointIDsFromHistory()
	require.GreaterOrEqual(t, len(checkpointIDsAfterSecond), 2, "Should have two checkpoints")
	checkpointC := checkpointIDsAfterSecond[0]
